import Blockly from 'blockly/core';
import 'blockly/blocks';
import { pythonGenerator } from 'blockly/python';

const ProgramStructureBlocks = {
  init: function() {
    // Define the try-except block
    Blockly.Blocks['program_try_except'] = {
      init: function() {
        this.appendDummyInput()
            .appendField('Program Structure');
        this.appendStatementInput('TRY')
            .setCheck(null)
            .appendField('try');
        
        // Add initial except block
        this.appendStatementInput('EXCEPT_0')
            .setCheck(null)
            .appendField('except')
            .appendField(new Blockly.FieldTextInput('Exception'), 'EXCEPTION_0');
            
        this.setColour(230);
        this.setTooltip('Main program structure with try-except');
        this.setDeletable(false);
        this.setMovable(false);
      },
      mutationToDom: function() {
        const container = document.createElement('mutation');
        const exceptCount = this.exceptCount || 1;
        container.setAttribute('except_count', exceptCount);
        return container;
      },
      domToMutation: function(xmlElement) {
        const exceptCount = parseInt(xmlElement.getAttribute('except_count') || '1');
        this.exceptCount = exceptCount;
        this.updateShape_(exceptCount);
      },
      updateShape_: function(exceptCount) {
        // Remove all except blocks
        for (let i = 0; i < this.exceptCount; i++) {
          this.removeInput('EXCEPT_' + i);
        }
        
        // Add new except blocks
        for (let i = 0; i < exceptCount; i++) {
          this.appendStatementInput('EXCEPT_' + i)
              .setCheck(null)
              .appendField('except')
              .appendField(new Blockly.FieldTextInput('Exception'), 'EXCEPTION_' + i);
        }
        
        // Add "Add Exception" button if not at max
        if (exceptCount < 5) {
          this.appendDummyInput()
              .appendField(new Blockly.FieldImage(
                  'data:image/svg+xml;base64,',
                  24, 24, 'Add Exception'
              ));
        }
      },
      onchange: function(e) {
        if (e.type === Blockly.Events.FINISHED_LOADING) {
          // Initialize the block with one except block
          this.exceptCount = 1;
          this.updateShape_(1);
        }
      }
    };

    // Register the Python generator for the try-except block
    pythonGenerator['program_try_except'] = function(block) {
      const tryStatements = pythonGenerator.statementToCode(block, 'TRY');
      const exceptCount = block.exceptCount || 1;
      let exceptCode = '';
      
      // Generate except blocks
      for (let i = 0; i < exceptCount; i++) {
        const exceptionType = block.getFieldValue('EXCEPTION_' + i);
        const exceptStatements = pythonGenerator.statementToCode(block, 'EXCEPT_' + i);
        exceptCode += `    except ${exceptionType} as e${i}:\n` +
                     `        print(f"Error: {e${i}}")\n` +
                     `        ${exceptStatements}\n`;
      }
      
      // Add common imports and setup
      const imports = `import time\nimport sys\n\n`;
      
      // Create the main program structure
      const code = `${imports}def main():\n` +
                  `    try:\n` +
                  `        ${tryStatements}\n` +
                  `${exceptCode}\n` +
                  `if __name__ == "__main__":\n` +
                  `    main()\n`;
      
      return code;
    };
  }
};

export default ProgramStructureBlocks;
